//! Python: the PyO3 extension module `azul` (`target/codegen/python_api.rs`,
//! generated by `doc/src/codegen/v2/lang_python.rs`).
//!
//! Spellings: api.json constructors keep their snake_case names
//! (`CssProperty.text_color(..)`, `PixelValue.px(10.0)`); every enum variant
//! is a PascalCase static method (`LayoutWidth.Px(pv)`, unit
//! `LayoutWidth.Auto()`, also the monomorphized `LayoutWidthValue.Exact(..)`
//! and the shadowed `CssProperty.Width(..)`), a C-like variant a class
//! attribute (`LayoutDisplay.Flex`; `None` needs `getattr`). There is no
//! keyword constructor for structs: `X.default()` + attribute setters, which
//! the generated `_with(X.default(), field=value)` helper chains into an
//! expression. Vec types only have `create()` / `from_item(x)`, so a style is
//! returned as a plain Python list and a nested Vec of 2+ items (gradient
//! stops, several font families) cannot be built. Variants with a `String`
//! payload are not exposed.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{EnumShape, Expr, Ident, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, native_list, unicode_u4, uses_struct, ConcatPart,
        ExprSyntax, MethodLayout,
    },
    CodegenBackend, GeneratedFile,
};

/// A parameter's Python name (a keyword gets a `_`).
fn py_param(name: &Ident) -> String {
    let s = name.snake();
    if KEYWORDS.contains(&s.as_str()) || s == "azul" {
        format!("{s}_")
    } else {
        s
    }
}

/// The Python printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Python;

const KEYWORDS: &[&str] = &[
    "False", "None", "True", "and", "as", "assert", "async", "await", "break", "class",
    "continue", "def", "del", "elif", "else", "except", "finally", "for", "from", "global", "if",
    "import", "in", "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return", "try",
    "while", "with", "yield",
];

impl ExprSyntax for Python {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" | "inf" | "-inf" => format!("float(\"{text}\")"),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "True" } else { "False" })
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("\"{}\"", escape_quoted(s, &[], &unicode_u4)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("{class}.{method}"), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        let access = if KEYWORDS.contains(&variant) {
            format!("getattr({ty}, \"{variant}\")")
        } else {
            format!("{ty}.{variant}")
        };
        match shape {
            EnumShape::CLike => Doc::text(access),
            EnumShape::Tagged | EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                Doc::call(access, args, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let mut args = vec![Doc::text(format!("{ty}.default()"))];
        args.extend(
            fields
                .into_iter()
                .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{k}=")), v])),
        );
        Doc::call("_with", args, broken)
    }

    fn vec(&self, ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        match items.len() {
            0 => Doc::text(format!("{ty}.create()")),
            1 => Doc::call(format!("{ty}.from_item"), items, broken),
            // unreachable: `limitation` rejects these
            _ => Doc::list("[", items, ", ", "]", false, broken, true),
        }
    }

    fn unsupported(&self, _what: &str) -> Doc {
        Doc::text("None")
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        None
    }

    /// A builder chain, one `.with_x(..)` per line (the item wraps it in
    /// parentheses).
    fn method(&self, recv: Doc, _class: &str, method: &str, args: Vec<Doc>, layout: MethodLayout) -> Doc {
        Doc::chained(recv, Doc::call(format!(".{method}"), args, layout.args_tall))
    }

    fn param(&self, name: &Ident) -> Doc {
        Doc::text(py_param(name))
    }

    fn item_call_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `render_card("Hi", title)`: another function of the module (the
    /// native string arguments are the default `native_string`).
    fn item_call(&self, item: &Ident, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(item.snake(), args, broken)
    }

    /// An f-string.
    fn concat(&self, parts: &[ConcatPart<'_>]) -> Doc {
        let mut f = String::from("f\"");
        for p in parts {
            match p {
                ConcatPart::Lit(s) => f.push_str(
                    &escape_quoted(s, &[], &unicode_u4)
                        .replace('{', "{{")
                        .replace('}', "}}"),
                ),
                ConcatPart::Param(i) => {
                    f.push('{');
                    f.push_str(&py_param(i));
                    f.push('}');
                }
            }
        }
        f.push('"');
        Doc::text(f)
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Vec { ty, items, .. } if items.len() >= 2 => Some(format!(
                "the Python bindings cannot build a {ty} of 2+ items (only create() / from_item())"
            )),
            Expr::Variant {
                ty, variant, args, ..
            } if args.iter().any(|a| matches!(a, Expr::Str(_))) => Some(format!(
                "{ty}.{variant} has a String payload, which the Python bindings do not expose"
            )),
            Expr::Struct { ty, fields } => fields
                .iter()
                .find(|(k, _)| KEYWORDS.contains(&k.as_str()))
                .map(|(k, _)| format!("{ty}.{k} is a Python keyword and not exposed")),
            _ => None,
        }
    }
}

fn item_def(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Python, item) {
        out.push_str(&format!("# {line}\n"));
    }
    let name = item.name.snake();
    // Parameters default to the values the item was made with.
    let params = item
        .params
        .iter()
        .map(|p| match &p.default {
            Some(d) => format!(
                "{}={}",
                py_param(&p.name),
                crate::codegen::lang::expr_doc(&Python, d).flat()
            ),
            None => py_param(&p.name),
        })
        .collect::<Vec<_>>()
        .join(", ");
    let body = native_list(&Python, &item.value, "[", "]")
        .map(Ok)
        .unwrap_or_else(|| item_doc(&Python, item));
    match body {
        // A builder chain spans lines: inside parentheses.
        Ok(doc) if matches!(doc, Doc::Chain { .. }) && doc.is_multiline() => out.push_str(&format!(
            "def {name}({params}):\n    return (\n        {}\n    )\n",
            render(&doc, "    ", 2)
        )),
        Ok(doc) => out.push_str(&format!(
            "def {name}({params}):\n    return {}\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "def {name}({params}):\n    # not expressible with the Python bindings: {reason}\n    \
             return None\n"
        )),
    }
    out
}

/// The app around a DOM module (`m.app`).
fn python_app_main(m: &Module) -> String {
    let Some(app) = &m.app else {
        return String::new();
    };
    let root = app.root.snake();
    let body = if app.is_body {
        format!("{root}()")
    } else {
        format!("Dom.create_body().with_child({root}())")
    };
    format!(
        "# {} - generated by AzBuilder (azul-css codegen, Python).\n# Needs the azul extension \
         module next to this file: build it with\n# `cargo build --release -p azul-dll \
         --features python-extension` and copy\n# libazul.so / libazul.dylib to azul.so (azul.pyd \
         on Windows).\nfrom azul import *\nfrom ui import {root}\n\nclass AppData:\n    \
         pass\n\ndef layout(data, info):\n    return {body}\n\ndef main():\n    app = \
         App.create(AppData(), AppConfig.create())\n    \
         app.run(WindowCreateOptions.create(layout))\n\nif __name__ == \"__main__\":\n    \
         main()\n",
        app.title.replace(|c: char| c == '\n' || c == '\r', " "),
    )
}

impl CodegenBackend for Python {
    fn lang(&self) -> &'static str {
        "python"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["py", "python3"]
    }

    fn display_name(&self) -> &'static str {
        "Python"
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn extension(&self) -> &'static str {
        "py"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (Python). Do not edit by hand.\nfrom azul import *\n",
        );
        if uses_struct(m) {
            out.push_str(
                "\ndef _with(value, **fields):\n    for name, field in fields.items():\n        \
                 setattr(value, name, field)\n    return value\n",
            );
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_def(item));
        }
        if let Some(lib) = &m.library {
            out.push_str(&format!(
                "\n# Registering the `{}` library (AppConfig.add_component_library) needs a\n# \
                 ComponentDef whose render function is a native callback, which the Python\n# \
                 bindings cannot build: register it from the Rust, C or C++ export. Each\n# \
                 render_* function above keeps the component's defaults as its keyword defaults.\n",
                lib.name.replace(|c: char| c == '\n' || c == '\r', " ")
            ));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        if m.app.is_some() {
            return vec![
                GeneratedFile {
                    path: "ui.py".to_string(),
                    contents: self.emit_module(m),
                },
                GeneratedFile {
                    path: "main.py".to_string(),
                    contents: python_app_main(m),
                },
            ];
        }
        let names: Vec<String> = m.items.iter().map(|i| i.name.snake()).collect();
        let mut main = format!(
            "# Needs the azul extension module next to this file: build it with\n# `cargo build \
             --release -p azul-dll --features python-extension` and copy\n# libazul.so / \
             libazul.dylib to azul.so (azul.pyd on Windows).\nfrom styles import {}\n",
            names.join(", ")
        );
        for name in &names {
            main.push_str(&format!(
                "\n{name}_value = {name}()\nprint(\"{name}: %d properties\" % len({name}_value))\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.py".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.py".to_string(),
                contents: main,
            },
        ]
    }
}
